return items.filter(item => {
  const metrics = item.json.metrics || {};
  const likes = metrics.likes || 0;
  const replies = metrics.replies || 0;

  return (likes + replies > 40) && (likes > 30) && (replies > 8);
});

const now = new Date();
const twoDaysAgo = new Date(now.getTime() - 2 * 24 * 60 * 60 * 1000);
const since = twoDaysAgo.toISOString().split('T')[0] + "_00:00:00_UTC";

return [
  {
    json: {
      since: since
    }
  }
];

function formatDate(dateString) {
  return new Date(dateString).toLocaleString('en-US', { timeZone: 'UTC' });
}

function extractMediaUrls(tweet) {
  const mediaArray = tweet.extendedEntities?.media || [];

  return mediaArray.map(mediaItem => {
    // 優先用 media_results 裡的 result.media_url_https
    const fromResult = mediaItem.media_results?.result?.media_url_https;
    // fallback 用直接存在 mediaItem 裡的 media_url_https
    const fallback = mediaItem.media_url_https;

    return fromResult || fallback;
  }).filter(Boolean); // 過濾掉 null/undefined
}

const tweets = items.map(item => {
  const t = item.json;

  const mediaUrls = extractMediaUrls(t);

  return {
    tweetText: t.text || '',
    tweetUrl: t.twitterUrl || t.url || '',
    author: {
      name: t.author?.name || '',
      username: t.author?.userName || '',
      profileUrl: t.author?.twitterUrl || '',
      profileImage: t.author?.profilePicture || '',
      verified: t.author?.isVerified || false,
      followers: t.author?.followers || 0,
      bio: t.author?.profile_bio?.description || '',
    },
    metrics: {
      likes: t.likeCount || 0,
      retweets: t.retweetCount || 0,
      replies: t.replyCount || 0,
      quotes: t.quoteCount || 0,
      views: t.viewCount || 0,
      bookmarks: t.bookmarkCount || 0,
    },
    createdAt: formatDate(t.createdAt),
    lang: t.lang || 'und',
    isReply: t.isReply || false,
    isPinned: t.isPinned || false,
    media: mediaUrls,
  };
});

return tweets.map(t => ({ json: t }));

const timeframeMs = 2.5 * 24 * 60 * 60 * 1000; // 你改成了 3 天，這很精準
const now = new Date();
const existingUrls = new Set($("Get Existing Record URLs").first().json.urls);  
const MIN_SCORE_THRESHOLD = 100; // 門檻設定：例如至少要有連結 + 一個關鍵字，或是有一定互動
const MAX_OUTPUT_COUNT = 40;    // 只取最強的前 30 則，避免 AI 運算過載

const results = items
  .map(item => {
    const t = item.json;
    const createdAt = new Date(t.createdAt);
    const isWithinTimeframe = (now - createdAt <= timeframeMs);

    // 1. 基礎社群互動分
    let socialScore = (t.metrics.likes || 0) * 1 + 
                      (t.metrics.replies || 0) * 1.5 + 
                      (t.metrics.retweets || 0) * 2 +
                      (t.metrics.bookmarks || 0) * 3;

    // 2. 內容加權分
    let qualityScore = 0;

    const lowerText = t.tweetText.toLowerCase();

    const totalScore = socialScore + qualityScore;

    return {
      ...t,
      totalScore,
      isRecent: isWithinTimeframe
    };
  })
  // --- 這裡開始是真正的 Filter 邏輯 ---
  .filter(tweet => {
    // 條件 A：必須在時間範圍內
    if (!tweet.isRecent) return false;

    // 條件 B：分數必須高於門檻 (過濾掉完全沒人理且沒內容的推文)
    if (tweet.totalScore < MIN_SCORE_THRESHOLD) return false;

    // 條件 C：排除內容過短的廢文 (例如小於 15 個字且沒有連結)
    if (tweet.tweetText.length < 15 && !tweet.tweetText.includes('http')) return false;

    // 條件 D：排除已存在資料庫的貼文
    if (!existingUrls.has(tweet.tweetUrl)) return false;

    return true;
  })
  // 排序：分數最高的排前面
  .sort((a, b) => b.totalScore - a.totalScore)
  // 限制數量：只輸出最精華的部分
  .slice(0, MAX_OUTPUT_COUNT)
  .map(tweet => ({ json: tweet }));

return results;

function escapeHtml(str) {
  return str?.replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/\n/g, "<br>") || '';
}

const htmlBlocks = items.map(item => {
  const t = item.json;
  const author = t.author || {};
  const metrics = t.metrics || {};
  const media = t.media || [];

  const mediaBlock = media.length > 0
    ? `
      <div style="margin-top:12px; text-align:center;">
        ${media.map(url => `<img src="${url}" style="max-width:100%; max-height:400px; border-radius:12px; margin:10px auto; display:block;">`).join('')}
      </div>
    `
    : '';

  return `
    <div style="border:1px solid #e6ecf0; border-radius:16px; padding:20px; margin-bottom:30px; font-family:Helvetica, Arial, sans-serif; background:#ffffff; max-width:700px; margin:auto;">
      <!-- Author Section -->
      <div style="display:flex; align-items:center; gap:12px; margin-bottom:12px;">
        <img src="${author.profileImage}" width="48" height="48" style="border-radius:50%; border:1px solid #ccc;">
        <div>
          <a href="${author.profileUrl}" target="_blank" style="text-decoration:none; color:#0f1419; font-weight:bold; font-size:16px;">@${author.username}</a>
          <div style="font-size:13px; color:#536471;">${escapeHtml(author.bio)}</div>
        </div>
      </div>

      <!-- Tweet Text -->
      <div style="font-size:15px; color:#0f1419; line-height:1.6; margin-bottom:12px;">
        ${escapeHtml(t.tweetText)}
      </div>

      <!-- Media -->
      ${mediaBlock}

      <!-- Tweet Actions -->
      <div style="font-size:14px; color:#536471; margin-top:12px; display:flex; flex-wrap:wrap; gap:16px;">
        <span>❤️ <strong>${metrics.likes}</strong> Likes</span>
        <span>💬 <strong>${metrics.replies}</strong> Replies</span>
        <span>🔁 <strong>${metrics.retweets}</strong> Retweets</span>
        <span>👁️ <strong>${metrics.views}</strong> Views</span>
      </div>

      <!-- Timestamp + Link -->
      <div style="margin-top:12px; font-size:13px; color:#657786;">
        🕒 ${t.createdAt} · <a href="${t.tweetUrl}" target="_blank" style="color:#1da1f2; text-decoration:none;">View on Twitter</a>
      </div>
    </div>
  `;
});

return [
  {
    json: {
      html: htmlBlocks.join('\n')
    }
  }
];

